void loop() {
  time_t now;
  struct tm timeinfo;
  time(&now);
  localtime_r(&now, &timeinfo);

  if (timeinfo.tm_year < (2016 - 1900)) { // Если год меньше 2016 — синхронизации еще не было
    Serial.println("Time not available yet");
    delay(1000);
    return;
  }

  char buffer[80];
  strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S %A", &timeinfo);
  Serial.println(buffer);
  delay(1000);
}
